import SwiftUI

// 子视图：不拥有数据，只是「借用」父视图的 step
struct StepControlView: View {
    // @Binding 表示绑定到父视图的某个 @State
    @Binding var step: Int

    var body: some View {
        HStack(spacing: 16) {
            Button("➖") {
                if step > 1 { step -= 1 }
            }
            .buttonStyle(.bordered)

            Text("步长：\(step)")
                .font(.headline)
                .frame(width: 110)

            Button("➕") {
                if step < 5 { step += 1 }
            }
            .buttonStyle(.bordered)
        }
    }
}

// 父视图：数据的真正拥有者（Source of Truth）
struct WaterCounterView: View {
    // @State 让视图持有这份数据，数据变化时 UI 自动刷新
    @State private var cups: Int = 0
    @State private var step: Int = 1

    var body: some View {
        VStack(spacing: 24) {
            Text("今天喝了 \(cups) 杯水 💧")
                .font(.largeTitle)

            // 用 $ 把绑定传给子视图
            StepControlView(step: $step)

            Button("喝一杯") {
                cups += step        // 修改 @State，界面立即更新
            }
            .buttonStyle(.borderedProminent)

            Button("重置") {
                cups = 0
            }
            .tint(.red)
        }
        .padding()
    }
}

